mapper.select:


    v.deleted_at is null
     AND v.user_id = #{userId}
     AND v.dept_id = #{deptId}
     AND v.event_type = #{eventType}
     AND v.student_name like concat('%', #{studentName}, '%')
     AND v.location like concat('%', #{location}, '%')
     AND date(v.record_date) = date(#{recordDate})
     AND date(coalesce(v.record_date, v.create_time)) >= #{params.beginTime}
     AND date(coalesce(v.record_date, v.create_time)) <= #{params.endTime}

        AND (v.student_name like concat('%', #{keyword}, '%')
          or v.detail like concat('%', #{keyword}, '%')
          or v.raw_text like concat('%', #{keyword}, '%')
          or v.location like concat('%', #{keyword}, '%'))

    ${params.dataScope}

order by v.record_date desc, v.record_id desc



    v.deleted_at is not null
     AND v.user_id = #{userId}
     AND v.event_type = #{eventType}
    ${params.dataScope}

order by v.deleted_at desc, v.record_id desc

select date_format(coalesce(v.record_date, v.create_time), '%Y-%m') as month, v.event_type, count(*) as cnt from visit_record v
v.deleted_at is null AND date_format(coalesce(v.record_date, v.create_time), '%Y-%m-%d') >= #{params.beginTime} ${params.dataScope}
group by date_format(coalesce(v.record_date, v.create_time), '%Y-%m'), v.event_type

mapper.update:
update visit_record
event_type = #{eventType}, location = #{location}, student_name = #{studentName}, detail = #{detail}, raw_text = #{rawText}, record_date = #{recordDate}, update_by = #{updateBy}, update_time = sysdate()
where record_id = #{recordId}
